import openapiJson from "../dist/openapi.json";
import operationsJson from "../dist/operations.json";

export type { paths, components } from "./generated/schema";
export { createApiClient, type ApiClient, type ApiClientOptions } from "./client";
export { zodForComponent } from "./zod";

/** The bundled OpenAPI 3.1 document (generated by `pnpm gen` from contracts/**). */
export const openapiDocument = openapiJson as unknown as {
  openapi: string;
  paths: Record<string, Record<string, Record<string, unknown>>>;
  components: { schemas: Record<string, unknown> };
};

export interface OperationInfo {
  operationId: string;
  method: string;
  path: string;
  permission: string | null;
  scope: "tenant" | "seller-account" | "none";
}

/** operationId -> method, path, x-permission, x-scope. Used by the API boot check and guard. */
export const contractOperations = operationsJson as OperationInfo[];
